def get_urls(self):
    urls = []
    for prefix, viewset, basename in self.registry:
        # برای هر Route
        for route in self.routes:
            # URL را فرمت کن
            url = route.url.format(prefix=prefix, lookup=lookup, ...)

            # Mapping از متد به action
            mapping = route.mapping

            # پیدا کردن اکشن‌های @action
            for method, action in mapping.items():
                handler = getattr(viewset, action, None)
                if handler:
                    # ساخت view
                    view = viewset.as_view(mapping, **route.initkwargs)
                    name = route.name.format(basename=basename)
                    urls.append(path(url, view, name=name))
    return urls

def action(methods=None, detail=None, url_path=None, url_name=None, **kwargs):
    def decorator(func):
        func.mapping = MethodMapper(func, methods)
        func.detail = detail
        func.url_path = url_path or func.__name__
        func.url_name = url_name or func.__name__.replace("_", "-")
        func.kwargs = kwargs
        return func
    return decorator


